-- Canonical fixed DDL from Python SQLiteSessionStore, generated by tests/generate_fixtures.py.
CREATE TABLE IF NOT EXISTS monitoring_schema (version INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS monitoring_records (
        kind TEXT NOT NULL, id TEXT NOT NULL, project_id TEXT NOT NULL,
        created_at TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(kind,id));

CREATE INDEX IF NOT EXISTS monitoring_scope_time
        ON monitoring_records(kind,project_id,created_at,id);

CREATE TABLE IF NOT EXISTS monitoring_webhooks(
        project_id TEXT PRIMARY KEY,url TEXT NOT NULL,secret TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS monitoring_notifications(
        id TEXT PRIMARY KEY,project_id TEXT NOT NULL,created_at TEXT NOT NULL,payload TEXT NOT NULL,
        state TEXT NOT NULL,attempts INTEGER NOT NULL,next_at TEXT,error TEXT,lease_until TEXT,acknowledged_at TEXT);

CREATE INDEX IF NOT EXISTS monitoring_notifications_scope_time
        ON monitoring_notifications(project_id,created_at DESC,id DESC);

CREATE INDEX IF NOT EXISTS monitoring_notifications_pending
        ON monitoring_notifications(state,next_at,lease_until,created_at,id);

CREATE TABLE IF NOT EXISTS monitoring_sessions(
        project_id TEXT NOT NULL,session_id TEXT NOT NULL,PRIMARY KEY(project_id,session_id));

CREATE INDEX IF NOT EXISTS monitoring_event_sources ON monitoring_records(
        kind,project_id,json_extract(payload,'$.event_id'),json_extract(payload,'$.sweep_id'));

CREATE INDEX IF NOT EXISTS monitoring_search_marks ON monitoring_records(
        kind,project_id,json_extract(payload,'$.search_session_id'),created_at DESC,id DESC);

CREATE INDEX IF NOT EXISTS monitoring_state ON monitoring_records(kind,project_id,json_extract(payload,'$.state'),id);

CREATE INDEX IF NOT EXISTS monitoring_open_run ON monitoring_records(kind,project_id,
        json_extract(payload,'$.state'),json_extract(payload,'$.run_session_id'),json_extract(payload,'$.baseline_id'),id);

CREATE INDEX IF NOT EXISTS monitoring_receiver_pending ON monitoring_records(
        kind,project_id,json_extract(payload,'$.analysis.state'),
        json_extract(payload,'$.source_refs[#-1].session_id'),json_extract(payload,'$.last_seen') DESC,id DESC);

CREATE TABLE IF NOT EXISTS instrument_artifacts (
            id TEXT PRIMARY KEY, session_id TEXT NOT NULL, stream_id TEXT NOT NULL,
            schema_version INTEGER NOT NULL CHECK(schema_version=1), kind TEXT NOT NULL,
            mime_type TEXT NOT NULL, filename TEXT NOT NULL, sha256 TEXT NOT NULL,
            created_at TEXT NOT NULL, payload BLOB NOT NULL, metadata_json TEXT NOT NULL,
            FOREIGN KEY(stream_id,session_id) REFERENCES streams(id,session_id) ON DELETE CASCADE
        );

CREATE INDEX IF NOT EXISTS instrument_artifacts_scope_time
            ON instrument_artifacts(session_id,stream_id,created_at,id);

CREATE TABLE IF NOT EXISTS sessions (
                id TEXT PRIMARY KEY,
                contract_version INTEGER NOT NULL,
                name TEXT NOT NULL,
                state TEXT NOT NULL,
                created_at TEXT NOT NULL,
                started_at TEXT,
                ended_at TEXT,
                metadata_json TEXT NOT NULL
            );

CREATE TABLE IF NOT EXISTS streams (
                id TEXT PRIMARY KEY,
                session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
                device TEXT NOT NULL,
                role TEXT NOT NULL,
                level_unit TEXT NOT NULL,
                label TEXT NOT NULL,
                port TEXT,
                model TEXT,
                serial_number TEXT,
                firmware TEXT,
                state TEXT NOT NULL,
                capabilities_json TEXT NOT NULL,
                settings_json TEXT NOT NULL,
                UNIQUE (id, session_id)
            );

CREATE TABLE IF NOT EXISTS sweeps (
                id TEXT PRIMARY KEY,
                session_id TEXT NOT NULL,
                stream_id TEXT NOT NULL,
                started_at TEXT NOT NULL,
                ended_at TEXT NOT NULL,
                frequencies_json TEXT NOT NULL,
                levels_json TEXT NOT NULL,
                level_unit TEXT NOT NULL,
                settings_json TEXT NOT NULL,
                FOREIGN KEY (stream_id, session_id)
                    REFERENCES streams(id, session_id) ON DELETE CASCADE
            );

CREATE INDEX IF NOT EXISTS sweeps_stream_time
                ON sweeps(stream_id, started_at, id);

CREATE TABLE IF NOT EXISTS observations (
                id TEXT PRIMARY KEY,
                session_id TEXT NOT NULL,
                stream_id TEXT NOT NULL,
                started_at TEXT NOT NULL,
                ended_at TEXT NOT NULL,
                frequency_hz INTEGER NOT NULL,
                mode TEXT NOT NULL,
                level REAL,
                level_unit TEXT NOT NULL,
                squelch_open INTEGER,
                decoded_mode TEXT,
                audio_uri TEXT,
                metadata_json TEXT NOT NULL,
                FOREIGN KEY (stream_id, session_id)
                    REFERENCES streams(id, session_id) ON DELETE CASCADE
            );

CREATE INDEX IF NOT EXISTS observations_stream_time
                ON observations(stream_id, started_at, id);

CREATE INDEX IF NOT EXISTS observations_target_time ON observations (
                session_id, stream_id, frequency_hz,
                (CASE WHEN instr(started_at, '.') = 0
                    THEN replace(started_at, 'Z', '.000000Z')
                    ELSE started_at END)
            );

CREATE TABLE IF NOT EXISTS events (
                sequence INTEGER PRIMARY KEY,
                event_type TEXT NOT NULL,
                occurred_at TEXT NOT NULL,
                session_id TEXT,
                payload_json TEXT NOT NULL
            );

CREATE INDEX IF NOT EXISTS events_session_sequence
                ON events(session_id, sequence);

CREATE TABLE IF NOT EXISTS candidates (
                id TEXT PRIMARY KEY,
                session_id TEXT NOT NULL,
                source_stream_id TEXT NOT NULL,
                started_at TEXT NOT NULL,
                ended_at TEXT NOT NULL,
                center_frequency_hz INTEGER NOT NULL,
                bandwidth_hz INTEGER,
                peak_level REAL,
                level_unit TEXT NOT NULL,
                score REAL,
                observation_ids_json TEXT NOT NULL,
                state TEXT NOT NULL,
                UNIQUE (id, session_id),
                FOREIGN KEY (source_stream_id, session_id)
                    REFERENCES streams(id, session_id) ON DELETE CASCADE
            );

CREATE INDEX IF NOT EXISTS candidates_session_state
                ON candidates(session_id, state, started_at, id);

CREATE TABLE IF NOT EXISTS investigations (
                id TEXT PRIMARY KEY,
                session_id TEXT NOT NULL,
                candidate_id TEXT NOT NULL,
                target_stream_id TEXT NOT NULL,
                target_frequency_hz INTEGER NOT NULL,
                state TEXT NOT NULL,
                priority INTEGER NOT NULL,
                mode TEXT,
                created_at TEXT NOT NULL,
                started_at TEXT,
                ended_at TEXT,
                result_observation_ids_json TEXT NOT NULL,
                error TEXT, listening_started_at TEXT,
                FOREIGN KEY (candidate_id, session_id)
                    REFERENCES candidates(id, session_id) ON DELETE CASCADE,
                FOREIGN KEY (target_stream_id, session_id)
                    REFERENCES streams(id, session_id) ON DELETE CASCADE
            );

CREATE INDEX IF NOT EXISTS investigations_session_queue
                ON investigations(session_id, state, priority DESC, created_at, id);

CREATE UNIQUE INDEX IF NOT EXISTS sweeps_reference_owner
                ON sweeps(id, session_id, stream_id)
        ;

CREATE TABLE IF NOT EXISTS sweep_references (
                id TEXT PRIMARY KEY,
                session_id TEXT NOT NULL,
                stream_id TEXT NOT NULL,
                sweep_id TEXT NOT NULL,
                name TEXT NOT NULL,
                created_at TEXT NOT NULL,
                started_at TEXT NOT NULL,
                ended_at TEXT NOT NULL,
                level_unit TEXT NOT NULL CHECK (level_unit = 'dBm'),
                points INTEGER NOT NULL CHECK (points BETWEEN 1 AND 16384),
                UNIQUE (session_id, name),
                FOREIGN KEY (sweep_id, session_id, stream_id)
                    REFERENCES sweeps(id, session_id, stream_id)
            );

CREATE INDEX IF NOT EXISTS sweep_references_session_time
                ON sweep_references(session_id, created_at, id)
        ;

CREATE TABLE IF NOT EXISTS measurement_results (
                id TEXT PRIMARY KEY,
                session_id TEXT NOT NULL,
                stream_id TEXT NOT NULL,
                methodology TEXT NOT NULL,
                result_code TEXT NOT NULL CHECK (
                    result_code IN ('norm', 'not_norm', 'not_measured')
                ),
                frequency_hz INTEGER NOT NULL CHECK (
                    frequency_hz BETWEEN 0 AND 9007199254740991
                ),
                started_at TEXT NOT NULL,
                ended_at TEXT NOT NULL,
                values_json TEXT NOT NULL,
                created_at TEXT NOT NULL,
                FOREIGN KEY (session_id) REFERENCES sessions(id)
            );

CREATE INDEX IF NOT EXISTS measurement_results_session_time
                ON measurement_results(session_id, created_at, id)
        ;

CREATE INDEX IF NOT EXISTS measurement_results_methodology
                ON measurement_results(session_id, methodology, created_at)
        ;

CREATE INDEX IF NOT EXISTS monitoring_investigations_state_time ON investigations(state,created_at,id);

CREATE TABLE IF NOT EXISTS monitoring_sweep_index(
        sweep_id TEXT PRIMARY KEY REFERENCES sweeps(id) ON DELETE CASCADE,
        session_id TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT NOT NULL,
        min_hz INTEGER NOT NULL,max_hz INTEGER NOT NULL);

CREATE INDEX IF NOT EXISTS monitoring_sweep_index_scope_time
        ON monitoring_sweep_index(session_id,started_at DESC,sweep_id DESC);

CREATE TABLE IF NOT EXISTS sweep_ingestion (
                sequence INTEGER PRIMARY KEY AUTOINCREMENT,
                sweep_id TEXT NOT NULL UNIQUE,
                session_id TEXT NOT NULL,
                stream_id TEXT NOT NULL,
                FOREIGN KEY (sweep_id, session_id, stream_id)
                    REFERENCES sweeps(id, session_id, stream_id) ON DELETE CASCADE
            );

CREATE INDEX IF NOT EXISTS sweep_ingestion_session ON sweep_ingestion(session_id, sequence);

CREATE INDEX IF NOT EXISTS sweep_ingestion_stream ON sweep_ingestion(session_id, stream_id, sequence);
